func TestTokensRefill(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	l := mustNew(t, 1, 5, fc)
	l.AllowN(fc.t, 5)
	if got := l.Tokens(); got != 0 {
		t.Fatalf("tokens after drain = %v, want 0", got)
	}
	fc.Advance(2 * time.Second)
	if got := l.Tokens(); got != 2 {
		t.Fatalf("tokens after 2s = %v, want 2", got)
