func TestConcurrentAccess(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	l := mustNew(t, 1000, 1000, fc)
	done := make(chan struct{})
	var allowed int64
	var mu sync.Mutex
	for i := 0; i < 10; i++ {
		go func() {
			defer close(done)
			for j := 0; j < 100; j++ {
				if l.AllowN(fc.Now(), 1) {
					mu.Lock()
					allowed++
					mu.Unlock()
				}
			}
			done <- struct{}{}
		}()
	}
	for i := 0; i < 10; i++ {
		<-done
	}
	if allowed > 1000 {
		t.Fatalf("allowed %d, exceeds burst 1000", allowed)
	}
}
